//! The command registry (UI-W4-12…25): names, aliases, default keys, availability and status texts.
//!
//! Every frontend runs a command by its `id`. Names match the labels used on menus and buttons;
//! aliases add English words, and the full pinyin and pinyin initials of the name are generated so
//! that `qhps` finds 切换配色: read from `pinyin.json` (generated by `tools/gen_pinyin.py`) for the
//! fixed set of names. Keys use a neutral notation (`Ctrl+Shift+F5`) that frontends render per
//! platform.
//!
//! Names, statuses and reasons are Chinese message ids, translated when the palette answers
//! ([`label`], [`evaluate`]); in the English interface the English name is searched first and the
//! hits light up on it, the Chinese name, its pinyin and the aliases still find the command.
//!
//! The context carries plain facts about the view ([`ViewFacts`]) and the visualizations this
//! window can show ([`ShownVisual`]): the server fills them from its view and the layout registry.

use std::collections::HashMap;
use std::sync::LazyLock;

use sk_protocol::CAP_VISUALS;
use sk_protocol::palette::PaletteTab;

use super::fuzzy::{Scored, runs, score};
use crate::i18n::{self, Arg, plural, t, tr_with};

/// Colour mode -> its name (message id).
pub const COLOR_NAMES: [(&str, &str); 4] =
    [("class", "文件类别"), ("flat", "扁平"), ("time", "修改时间"), ("branch", "顶层分支")];
/// Built-in visualization -> its name (message id).
pub const VISUAL_NAMES: [(&str, &str); 3] = [("treemap", "树图"), ("flame", "火焰图"), ("flame_polar", "火焰-极坐标图")];

/// A visualization this window can switch to (registered, its capability announced: the
/// server's `view.showable`).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ShownVisual {
    pub id: String,
    /// its title in the current language
    pub title: String,
    /// also shown while comparing
    pub compare: bool,
}

/// What the commands need to know about the view (the server reads it from its `View`).
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ViewFacts {
    /// the selected node, when it is an element of the store (`0 < node < len`)
    pub selected: Option<u32>,
    pub has_trash: bool,
    /// the view shows a comparison
    pub compare: bool,
    pub back: bool,
    pub forward: bool,
    pub can_go_up: bool,
    /// class | flat | time | branch
    pub color_mode: String,
    pub visual: String,
    pub show_free: bool,
    pub show_unknown: bool,
    pub show_trash: bool,
}

/// Where the palette was opened.
#[derive(Clone, Debug, PartialEq)]
pub struct Context {
    pub tab: PaletteTab,
    pub scanning: bool,
    pub paused: bool,
    /// a hard scan was stopped with folders left to read (scan.continue)
    pub stopped: bool,
    /// hard | mft | snapshot: how the tree is being read
    pub method: String,
    pub has_scan: bool,
    /// scan | snapshot
    pub source: String,
    pub elapsed_s: Option<f64>,
    pub view: Option<ViewFacts>,
    pub snapshots: u32,
    pub basket: u32,
    /// what the session announced: visualizations, branch colours
    pub caps: Vec<String>,
    /// the visualizations this window can show (see [`ShownVisual`])
    pub visuals: Vec<ShownVisual>,
    /// the running app's version
    pub app_version: String,
    /// a newer release, "" when there is none
    pub update_version: String,
    pub update_checking: bool,
}

impl Context {
    pub fn new(tab: PaletteTab) -> Context {
        Context {
            tab,
            scanning: false,
            paused: false,
            stopped: false,
            method: "hard".into(),
            has_scan: false,
            source: "scan".into(),
            elapsed_s: None,
            view: None,
            snapshots: 0,
            basket: 0,
            caps: Vec::new(),
            visuals: Vec::new(),
            app_version: String::new(),
            update_version: String::new(),
            update_checking: false,
        }
    }

    pub fn selected_node(&self) -> Option<u32> {
        self.view.as_ref().and_then(|v| v.selected)
    }

    fn has_cap(&self, cap: &str) -> bool {
        self.caps.iter().any(|c| c == cap)
    }
}

/// None when satisfied, else the reason shown in place of the status (translated).
pub type Need = fn(&Context) -> Option<String>;
/// The status text (translated).
pub type Status = fn(&Context) -> String;

fn reason(text: &str) -> Option<String> {
    Some(t(text).to_owned())
}

fn need_scan(c: &Context) -> Option<String> {
    if c.has_scan { None } else { reason("需要先完成扫描") }
}
fn need_done(c: &Context) -> Option<String> {
    need_scan(c).or_else(|| if c.scanning { reason("扫描进行中") } else { None })
}
fn need_running(c: &Context) -> Option<String> {
    if c.scanning { None } else { reason("没有进行中的扫描") }
}
fn need_pausable(c: &Context) -> Option<String> {
    if !c.scanning {
        return reason("没有进行中的扫描");
    }
    if c.method == "mft" {
        return reason("MFT 快速扫描几秒内完成，无需暂停");
    }
    if c.paused { reason("已暂停") } else { None }
}
fn need_stopped(c: &Context) -> Option<String> {
    if c.stopped { None } else { reason("没有可以继续的扫描") }
}
fn need_paused(c: &Context) -> Option<String> {
    need_running(c).or_else(|| if c.paused { None } else { reason("扫描没有暂停") })
}
fn need_view(c: &Context) -> Option<String> {
    if c.view.is_some() { None } else { reason("需要先完成扫描") }
}
fn need_trash_view(c: &Context) -> Option<String> {
    match &c.view {
        None => reason("需要先完成扫描"),
        Some(v) if v.has_trash => None,
        Some(_) => reason("这次扫描里没有回收站"),
    }
}
/// A view of the scan itself: a comparison's view shows changes, its folders are not the scan's.
fn need_scan_view(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if c.view.as_ref().is_some_and(|v| v.compare) { reason("对比时不可用，先退出对比") } else { None })
}
fn need_selection(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if c.selected_node().is_some() { None } else { reason("没有选中项") })
}
fn need_back(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if c.view.as_ref().is_some_and(|v| v.back) { None } else { reason("没有可后退的位置") })
}
fn need_forward(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if c.view.as_ref().is_some_and(|v| v.forward) { None } else { reason("没有可前进的位置") })
}
fn need_up(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if c.view.as_ref().is_some_and(|v| v.can_go_up) { None } else { reason("已经在根") })
}
/// The visualizations the view can switch to in this window.
fn shown(c: &Context) -> Vec<&str> {
    let compare = c.view.as_ref().is_some_and(|v| v.compare);
    c.visuals.iter().filter(|v| v.compare || !compare).map(|v| v.id.as_str()).collect()
}
/// Cycling needs a second visualization this window can show.
fn need_visuals(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if shown(c).len() > 1 { None } else { reason("这种可视化在当前界面不可用") })
}
fn visual_ok(c: &Context, visual: &str) -> Option<String> {
    need_view(c).or_else(|| if shown(c).contains(&visual) { None } else { reason("这种可视化在当前界面不可用") })
}
fn need_treemap(c: &Context) -> Option<String> {
    visual_ok(c, "treemap")
}
fn need_flame(c: &Context) -> Option<String> {
    visual_ok(c, "flame")
}
fn need_flame_polar(c: &Context) -> Option<String> {
    visual_ok(c, "flame_polar")
}
fn need_branch(c: &Context) -> Option<String> {
    need_view(c).or_else(|| if c.has_cap(CAP_VISUALS) { None } else { reason("这种配色在当前界面不可用") })
}
fn need_snapshots(c: &Context) -> Option<String> {
    if c.snapshots > 0 { None } else { reason("没有快照") }
}
fn need_tab(c: &Context) -> Option<String> {
    if c.tab == PaletteTab::Scan { None } else { reason("需要先完成扫描") }
}
fn need_update(c: &Context) -> Option<String> {
    if c.update_version.is_empty() { reason("没有可用的更新") } else { None }
}

fn status_rescan(c: &Context) -> String {
    let method = t(if c.method == "mft" { "MFT 快速扫描" } else { "硬扫描" }).to_owned();
    match c.elapsed_s {
        Some(e) if c.source == "scan" => {
            let seconds = e.round_ties_even().max(1.0) as i64;
            tr_with("{method} · 约 {seconds} 秒", &[("method", method.into()), ("seconds", seconds.into())])
        }
        _ => method,
    }
}
fn color_name(mode: &str) -> String {
    COLOR_NAMES.iter().find(|(k, _)| *k == mode).map_or_else(|| mode.to_owned(), |(_, v)| t(v).to_owned())
}
fn status_color(c: &Context) -> String {
    c.view.as_ref().map_or_else(String::new, |v| tr_with("当前：{mode}", &[("mode", color_name(&v.color_mode).into())]))
}
/// A visualization's name: the built-in names, else its title, else its id.
pub fn visual_name(c: &Context, visual: &str) -> String {
    if let Some((_, v)) = VISUAL_NAMES.iter().find(|(k, _)| *k == visual) {
        return t(v).to_owned();
    }
    c.visuals.iter().find(|v| v.id == visual).map_or_else(|| visual.to_owned(), |v| v.title.clone())
}
fn status_visual(c: &Context) -> String {
    c.view.as_ref().map_or_else(String::new, |v| tr_with("当前：{name}", &[("name", visual_name(c, &v.visual).into())]))
}
fn shown_hidden(on: bool) -> String {
    t(if on { "当前：显示" } else { "当前：隐藏" }).to_owned()
}
fn status_free(c: &Context) -> String {
    c.view.as_ref().map_or_else(String::new, |v| shown_hidden(v.show_free))
}
fn status_unknown(c: &Context) -> String {
    c.view.as_ref().map_or_else(String::new, |v| shown_hidden(v.show_unknown))
}
fn status_trash(c: &Context) -> String {
    c.view.as_ref().map_or_else(String::new, |v| shown_hidden(v.show_trash))
}
fn status_basket(c: &Context) -> String {
    if c.basket == 0 {
        return t("空").to_owned();
    }
    plural(c.basket as i64, "{count} 项", "1 item", &[("count", crate::fmt::count(c.basket as i64).into())])
}
fn status_snapshots(c: &Context) -> String {
    plural(c.snapshots as i64, "{count} 个快照", "1 snapshot", &[("count", Arg::from(c.snapshots))])
}
fn status_update_check(c: &Context) -> String {
    if c.update_checking {
        return t("正在检查…").to_owned();
    }
    if !c.update_version.is_empty() {
        return tr_with("有新版本 {version}", &[("version", c.update_version.as_str().into())]);
    }
    if c.app_version.is_empty() {
        String::new()
    } else {
        tr_with("当前版本 {version}", &[("version", c.app_version.as_str().into())])
    }
}
fn status_export(_: &Context) -> String {
    "CSV · JSON · HTML".into()
}
fn status_update_version(c: &Context) -> String {
    c.update_version.clone()
}
fn status_app_version(c: &Context) -> String {
    c.app_version.clone()
}
fn current_if(on: bool) -> String {
    if on { t("当前").to_owned() } else { String::new() }
}
fn color_is(c: &Context, mode: &str) -> String {
    current_if(c.view.as_ref().is_some_and(|v| v.color_mode == mode))
}
fn visual_is(c: &Context, visual: &str) -> String {
    current_if(c.view.as_ref().is_some_and(|v| v.visual == visual))
}
fn pick_class(c: &Context) -> String {
    color_is(c, "class")
}
fn pick_flat(c: &Context) -> String {
    color_is(c, "flat")
}
fn pick_time(c: &Context) -> String {
    color_is(c, "time")
}
fn pick_branch(c: &Context) -> String {
    color_is(c, "branch")
}
fn pick_treemap(c: &Context) -> String {
    visual_is(c, "treemap")
}
fn pick_flame(c: &Context) -> String {
    visual_is(c, "flame")
}
fn pick_flame_polar(c: &Context) -> String {
    visual_is(c, "flame_polar")
}

/// A search key: the text and, for the name and its pinyin, the name index of each character.
pub type SearchKey = (String, Option<Vec<usize>>);

/// One command.
#[derive(Clone, Debug)]
pub struct Command {
    pub id: &'static str,
    /// message id (Chinese)
    pub name: &'static str,
    pub icon: &'static str,
    pub keys: &'static [&'static str],
    pub aliases: &'static [&'static str],
    /// 1–9: position in the empty-input list
    pub pinned: u8,
    pub needs: &'static [Need],
    pub status: Option<Status>,
    /// not wired up yet: disabled until then
    pub milestone: &'static str,
    /// only listed for a typed query (colour choices …)
    pub typed_only: bool,
    /// the name, its pinyin and initials, the aliases
    pub search: Vec<SearchKey>,
}

impl Command {
    /// Ends with '…': running it asks for one more choice.
    pub fn more(&self) -> bool {
        self.name.ends_with('…')
    }
}

struct Def {
    id: &'static str,
    name: &'static str,
    icon: &'static str,
    keys: &'static [&'static str],
    aliases: &'static [&'static str],
    pinned: u8,
    needs: &'static [Need],
    status: Option<Status>,
    milestone: &'static str,
    typed_only: bool,
}

const D: Def = Def {
    id: "",
    name: "",
    icon: "",
    keys: &[],
    aliases: &[],
    pinned: 0,
    needs: &[],
    status: None,
    milestone: "",
    typed_only: false,
};

