static PINYIN: LazyLock<HashMap<String, Vec<String>>> = LazyLock::new(|| {
    serde_json::from_str(include_str!("pinyin.json")).unwrap_or_else(|e| {
        tracing::warn!("pinyin.json is unreadable: {e}");
        HashMap::new()
    })
});

/// The pinyin of a command name, one entry per character (a character that is not a hanzi is
/// itself); `None` when the generated table misses the name (run `tools/gen_pinyin.py`).
pub fn syllables(name: &str) -> Option<&'static [String]> {
    PINYIN.get(name).map(Vec::as_slice)
}

/// (text, map from text index to name index or None) for the name, its pinyin and its aliases.
fn search_keys(name: &str, aliases: &[&str]) -> Vec<SearchKey> {
    let chars: Vec<char> = name.chars().collect();
    let mut full = String::new();
    let mut full_map = Vec::new();
    let mut initials = String::new();
    let mut init_map = Vec::new();
    if let Some(syl) = syllables(name)
        && syl.len() == chars.len()
    {
        for (i, (&ch, py)) in chars.iter().zip(syl).enumerate() {
            let mut one = py.chars();
            if one.next() == Some(ch) && one.next().is_none() {
                // not a hanzi
                if ch.is_alphanumeric() {
                    for l in ch.to_lowercase() {
                        full.push(l);
                        full_map.push(i);
                        initials.push(l);
                        init_map.push(i);
                    }
                }
                continue;
            }
            for p in py.chars() {
                full.push(p);
                full_map.push(i);
            }
            if let Some(first) = py.chars().next() {
                initials.push(first);
                init_map.push(i);
            }
        }
    }
    let mut keys: Vec<SearchKey> = vec![(name.to_owned(), Some((0..chars.len()).collect()))];
    if !full.is_empty() {
        keys.push((full, Some(full_map)));
        keys.push((initials, Some(init_map)));
    }
    keys.extend(aliases.iter().map(|a| ((*a).to_owned(), None)));
    keys
}

static REGISTRY: LazyLock<Vec<Command>> = LazyLock::new(|| {
    DEFS.iter()
        .map(|d| Command {
            id: d.id,
            name: d.name,
            icon: d.icon,
            keys: d.keys,
            aliases: d.aliases,
            pinned: d.pinned,
            needs: d.needs,
            status: d.status,
            milestone: d.milestone,
            typed_only: d.typed_only,
            search: search_keys(d.name, d.aliases),
        })
        .collect()
});

/// Every command, in registry order.
pub fn registry() -> &'static [Command] {
    &REGISTRY
}

/// A command by its id.
pub fn command(id: &str) -> Option<&'static Command> {
    REGISTRY.iter().find(|c| c.id == id)
}

/// The command's name in the current language (what [`match_command`] hits refer to).
pub fn label(cmd: &Command) -> String {
    t(cmd.name).to_owned()
}

/// (enabled, status text or the reason it is disabled), in the current language.
pub fn evaluate(cmd: &Command, ctx: &Context) -> (bool, String) {
    let status = cmd.status.map(|s| s(ctx)).unwrap_or_default();
    for need in cmd.needs {
        if let Some(reason) = need(ctx)
            && !reason.is_empty()
        {
            return (false, reason);
        }
    }
    if !cmd.milestone.is_empty() {
        let later = if cmd.milestone == "TODO" {
            t("还没有实现（见 TODO）").to_owned()
        } else {
            tr_with("{milestone} 接入", &[("milestone", cmd.milestone.into())])
        };
        return (false, if status.is_empty() { later } else { format!("{status} · {later}") });
    }
    (true, status)
}

/// The search keys in the current language: in a translated interface the shown name comes
/// first (hits map onto it), then the Chinese name, its pinyin and the aliases (no hits).
fn keys(cmd: &Command) -> std::borrow::Cow<'_, [SearchKey]> {
    if i18n::language() == i18n::SOURCE {
        return std::borrow::Cow::Borrowed(&cmd.search);
    }
    let shown = label(cmd);
    if shown == cmd.name {
        return std::borrow::Cow::Borrowed(&cmd.search);
    }
    let n = shown.chars().count();
    let mut out: Vec<SearchKey> = vec![(shown, Some((0..n).collect()))];
    out.extend(cmd.search.iter().map(|(text, _)| (text.clone(), None)));
    std::borrow::Cow::Owned(out)
}

/// Best fuzzy score over the name, its pinyin and its aliases (and the shown name, see above);
/// hits (character runs) are mapped onto the shown name ([`label`]).
pub fn match_command(cmd: &Command, query: &str) -> Option<Scored> {
    let mut best: Option<Scored> = None;
    for (k, (text, mapping)) in keys(cmd).iter().enumerate() {
        let Some((mut s, mut spans)) = score(query, text) else { continue };
        if k > 0 {
            s -= 4 * k as i64; // prefer the visible name, then pinyin, then aliases
        }
        match mapping {
            None => spans.clear(),
            Some(map) if k > 0 => {
                let mut idx: Vec<usize> = spans.iter().flat_map(|&(a, b)| (a..b).map(|i| map[i])).collect();
                idx.sort_unstable();
                idx.dedup();
                spans = runs(&idx);
            }
            Some(_) => {}
        }
        if best.as_ref().is_none_or(|b| s > b.0) {
            best = Some((s, spans));
        }
    }
    best
}

/// A command as the protocol sends it, with its hits (UTF-16) on the shown name.
pub fn protocol_command(cmd: &Command, ctx: &Context, hits: &[(usize, usize)]) -> sk_protocol::palette::PaletteCommand {
    let (enabled, status) = evaluate(cmd, ctx);
    let name = label(cmd);
    sk_protocol::palette::PaletteCommand {
        id: cmd.id.to_owned(),
        hits: super::fuzzy::protocol_spans(&name, hits),
        name,
        status,
        enabled,
        keys: cmd.keys.iter().map(|k| (*k).to_owned()).collect(),
        icon: cmd.icon.to_owned(),
        more: cmd.more(),
    }
}
